export function shell(content, active = "Übersicht") {
  const nav = ["Übersicht", "E-Mails", "Bewerbungen", "Kalender", "Aufgaben", "Fristen", "Einstellungen"];
  return `<div class="shell">
    <aside class="sidebar"><div class="side-top"><div class="side-title">Cockpit</div><div class="side-sub">Persönlicher Arbeitsbereich</div></div>
      <nav>${nav.map((item) => `<div class="nav-item ${item === active ? "active" : ""}"><span class="nav-ic">□</span><span>${item}</span></div>`).join("")}</nav>
      <div class="side-bottom"><div class="side-caption">Alle Systeme verbunden</div></div>
    </aside>
    <section class="content">${content}</section>
    <nav class="bottomnav">${nav.map((item) => `<div class="bn-item"><span class="bn-ic">□</span><span class="bn-lbl">${item}</span></div>`).join("")}</nav>
  </div>`;
}

export function overview() {
  return shell(`<main class="ov">
    <header class="ov-hero ov-command"><div class="ov-hero-copy"><div class="ov-eyebrow">Samstag, 6. September</div><h1>Guten Morgen, Marius</h1><p class="ov-sum">2 Antworten · 1 heute fällig</p></div>
      <nav class="ov-quick-actions"><a>＋ Aufgabe</a><a>✎ E-Mail</a><a class="primary">Neue Stelle</a></nav></header>
    <section class="ov-metrics"><a><span class="ov-metric-label">Offene Aufgaben</span><strong>7</strong><small>im Plan</small></a><a><span class="ov-metric-label">Ungelesen</span><strong>12</strong><small>3 wichtig</small></a><a><span class="ov-metric-label">Antworten</span><strong>2</strong><small>noch ausstehend</small></a><a><span class="ov-metric-label">Bewerbungen</span><strong>4</strong><small>2 warten</small></a></section>
    <div class="ov-priority-grid"><section class="ov-focus-panel"><div class="ov-section-head"><span>Mein Fokus</span><span class="ov-live"><i></i> automatisch priorisiert</span></div>
      <a class="ov-focus-card"><span class="ov-focus-icon">✓</span><span class="ov-focus-copy"><small>Nächster Schritt</small><strong>Bewerbungsunterlagen für das Praktikum prüfen</strong><span>Heute · hohe Priorität</span></span><span class="ov-focus-go">→</span></a>
      <div class="ov-agenda-list">${["Mathe-Aufgaben abschließen|Aufgabe · Heute","Trainer zurückrufen|Aufgabe · Morgen","Zeugnis hochladen|Frist · 10. Sep"].map((x,i)=>{const [a,b]=x.split("|");return `<a class="ov-agenda-row"><span class="ov-agenda-dot ${i===2?"deadline":""}"></span><span class="ov-agenda-main"><strong>${a}</strong><small>${b}</small></span><span>›</span></a>`}).join("")}</div><a class="ov-panel-link">Alle Aufgaben →</a></section>
      <section class="ov-inbox-panel"><div class="ov-section-head"><span>Neu im Posteingang</span><a>Alle anzeigen</a></div><div class="ov-mail-list">${["Anna Weber|Rückfrage zu deiner Bewerbung","Karate Dojo|Trainingsplan für nächste Woche","Schulbüro|Termin für die Beratung"].map((x,i)=>{const [a,b]=x.split("|");return `<a class="ov-mail-row"><span class="ov-avatar">${a[0]}</span><span class="ov-mail-copy"><strong>${a}</strong><span>${b}</span><small>${i?"iCloud":"Outlook"}</small></span><time>0${i+6}.09.</time></a>`}).join("")}</div><div class="ov-account-strip"><span>Outlook <b>7</b></span><span>iCloud <b>5</b></span></div></section></div>
    <div class="ov-secondary-grid"><section class="ov-app-panel"><div class="ov-section-head"><span>Bewerbungen</span><a>Manager öffnen</a></div><div class="ov-app-summary"><div><strong>4</strong><span>aktiv</span></div><div><strong>2</strong><span>in Vorbereitung</span></div><div><strong>2</strong><span>warten auf Antwort</span></div></div><a class="ov-next-app"><span><small>Nächste Handlung</small><strong>Unterlagen für „Werkstudent Marketing“ vorbereiten.</strong></span><b>→</b></a></section>
    <article class="tile"><div class="tile-h"><span class="tile-t">Nächste Termine</span><a>Kalender öffnen</a></div><div class="tile-inrow"><b>09:30</b><span class="il">Beratungsgespräch</span></div><div class="tile-inrow"><b>17:00</b><span class="il">Karate-Training</span></div></article></div>
  </main>`, "Übersicht");
}

export function mail() {
  const rows = ["Anna Weber|Rückfrage zur Bewerbung|Könntest du mir bitte noch das Zeugnis senden?","Karate Dojo|Training am Dienstag|Der Trainingsbeginn wurde auf 18 Uhr verschoben.","Schulbüro|Beratungstermin|Hiermit bestätigen wir deinen Termin."];
  return shell(`<div class="topbar"><div class="brand"><h1>E-Mails</h1></div><div class="spacer"></div><span class="status live">● Verbunden · 2 Postfächer</span><button class="btn small">Aktualisieren</button><button class="btn btn-primary small">Neue E-Mail</button></div>
    <div class="mail3 pane-read"><div class="msidebar"><div class="msidebar-scroll"><div class="oscroll-view"><button class="mfolder top active"><span class="mf-ic">□</span><span class="mf-lbl">Alle Postfächer</span><span class="mf-count">12</span></button><div class="macct"><button class="macct-h"><span>›</span><span class="macct-name">Outlook</span><span class="mf-count">7</span></button><div class="macct-folders"><button class="mfolder active">Posteingang</button><button class="mfolder">Gesendet</button><button class="mfolder">Archiv</button></div></div><div class="macct"><button class="macct-h"><span>›</span><span class="macct-name">iCloud</span><span class="mf-count">5</span></button></div><div class="msmart-h">Intelligente Ansichten</div><button class="mfolder">Antwort erforderlich</button><button class="mfolder">Wichtig</button><button class="mfolder">Newsletter</button></div></div></div>
    <div class="mlist"><div class="mlist-top"><input class="f-search" placeholder="Suchen…"><button class="btn small">↻</button></div><div class="mlist-filter"><button class="mfilter active">Alle</button><button class="mfilter">Ungelesen <span class="mfilter-count">12</span></button></div><div class="mlist-scroll"><div class="oscroll-view">${rows.map((r,i)=>{const [a,b,c]=r.split("|");return `<article class="mrow ${i===0?"sel unread":""}"><span class="mrow-dot"></span><div class="mrow-main"><div class="mrow-top"><span class="mrow-from">${a}</span><span class="mrow-time">09:${i}4</span></div><div class="mrow-subj">${b}</div><div class="mrow-prev">${c}</div><div class="mrow-tags"><span class="mrow-acct">Outlook</span></div></div></article>`}).join("")}</div></div></div>
    <div class="mread"><div class="dh"><div><h3>Rückfrage zu deiner Bewerbung</h3><div class="mail-account-line">Outlook · marius@example.de</div></div><button class="x">×</button></div><div class="db"><div class="rd-head"><div class="rd-from">Anna Weber</div><div class="rd-addr">anna@example.de</div><div class="meta-row"><span class="k">Datum</span><span class="v">06.09.2026, 09:04</span><span class="k">Kategorie</span><span class="v">Bewerbungen</span></div></div><div class="rd-want"><span class="rd-want-ic">✦</span><div><b>Einordnung:</b> Zeugnis wird für den nächsten Bewerbungsschritt benötigt.</div></div><div class="rd-body"><div class="rd-viewsel"><button class="on">Angepasst</button><button>Original</button><button>Nur Text</button></div><div class="rd-plain">Hallo Marius,<br><br>könntest du mir bitte noch dein aktuelles Zeugnis senden? Danach können wir den nächsten Gesprächstermin vereinbaren.<br><br>Viele Grüße<br>Anna Weber</div></div><div class="rd-actions"><div class="label">KI-Antwortvorschläge</div><div class="suggests"><button class="sug">Zeugnis heute senden</button><button class="sug">Rückfrage stellen</button><button class="sug custom">Eigene Antwort</button></div></div></div><div class="df"><button class="btn btn-primary">Antworten</button><button class="btn">Archivieren</button><button class="btn">Als ungelesen</button></div></div></div>`, "E-Mails");
}

export function calendar() {
  const cells = Array.from({length:42},(_,i)=>`<button class="cal-cell ${i===12?"today":""} ${i===15?"sel":""}"><span class="cal-dnum">${(i%30)+1}</span>${[4,12,15,22].includes(i)?`<span class="cal-dots"><span class="cal-chip">09:30 Termin</span><span class="cal-chip">Training</span></span>`:""}</button>`).join("");
  return shell(`<div class="page"><div class="page-head"><h1>Kalender</h1></div><div class="wrap-inner"><div class="cal"><div class="cal-toolbar"><div class="cal-nav"><button class="cal-btn">‹</button><div class="cal-title">September 2026</div><button class="cal-btn">›</button><button class="cal-today">Heute</button></div><div class="cal-right"><span class="cal-acct">marius@example.de</span><div class="cal-viewswitch"><button class="cal-vbtn">Woche</button><button class="cal-vbtn on">Monat</button><button class="cal-vbtn">Jahr</button><button class="cal-vbtn">Agenda</button></div></div></div><div class="cal-grid-wrap"><div class="cal-month-board"><div class="cal-wd">${["Mo","Di","Mi","Do","Fr","Sa","So"].map(x=>`<div class="cal-wdc">${x}</div>`).join("")}</div><div class="cal-grid">${cells}</div></div><aside class="cal-day"><div class="cal-day-kicker">Ausgewählter Tag</div><div class="cal-day-h">Dienstag, 16. September</div><a class="cal-ev"><span class="cal-ev-bar"></span><span class="cal-ev-time">09:30</span><span class="cal-ev-main"><span class="cal-ev-title">Beratungsgespräch</span><span class="cal-ev-meta">Privat · Video</span></span></a><a class="cal-ev"><span class="cal-ev-bar"></span><span class="cal-ev-time">18:00</span><span class="cal-ev-main"><span class="cal-ev-title">Karate-Training</span><span class="cal-ev-meta">Sporthalle</span></span></a></aside></div></div></div></div>`, "Kalender");
}

